// Generates website/src/content/docs/changelog.mdx from the repo-root CHANGELOG.md.
// Single source of truth: edit CHANGELOG.md, then `npm run build` (prebuild regenerates this).
// Do NOT hand-edit the generated file.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const sourcePath = resolve(here, "../../CHANGELOG.md");
const targetPath = resolve(here, "../src/content/docs/changelog.md");

const raw = readFileSync(sourcePath, "utf8");

// Strip the leading "# Changelog" H1 — Starlight's frontmatter title is the page's H1.
const body = raw.replace(/^#\s+Changelog\s*\n+/, "");

const output = `---
title: Changelog
description: All notable changes to go-atomic-write, generated from the root CHANGELOG.md.
---

<!--
  GENERATED by scripts/sync-changelog.mjs from ../../CHANGELOG.md.
  Do not edit by hand. Edit CHANGELOG.md and run \`npm run build\` (or \`npm run sync:changelog\`).
-->

${body}`;

writeFileSync(targetPath, output, "utf8");
console.log(`[sync-changelog] ${sourcePath} -> ${targetPath}`);
